def parse_duration(s):
    total = 0
    num = ''
    for char in s:
        if char.isdigit():
            num += char
        elif char == 'h':
            total += int(num) * 3600
            num = ''
        elif char == 'm':
            total += int(num) * 60
            num = ''
        elif char == 's':
            total += int(num)
            num = ''
    return total
